CREATE FUNCTION public.refresh_direccion_materialized_views(p_concurrent boolean DEFAULT false, OUT p_updated_at timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE plpgsql
    AS $$
BEGIN
