--
-- Name: mv_direccion_costo_ejecutivo_mensual; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_direccion_costo_ejecutivo_mensual AS
 WITH base AS (
         SELECT pr.organization_id,
            pr.company_id,
            pr.fiscal_entity_id,
            (EXTRACT(year FROM pr.fecha_pago))::integer AS anio,
            (EXTRACT(month FROM pr.fecha_pago))::integer AS mes,
            (COALESCE(NULLIF(prre.departamento, ''::text), NULLIF(pr.departamento, ''::text), 'Sin Departamento'::text))::character varying(120) AS departamento,
            pr.id AS pr_id,
            pr.total_percepciones,
            pr.num_dias_pagados,
            prre.salario_base_cot_apor AS sbc,
            COALESCE(NULLIF(prre.curp, ''::text), NULLIF(prre.num_empleado, ''::text), NULLIF(prre.rfc, ''::text)) AS empleado_key,
            prre.clave_ent_fed
           FROM ((public.payroll_receipts pr
             JOIN public.payroll_receptors prre ON ((prre.payroll_receipt_id = pr.id)))
             LEFT JOIN public.invoices inv ON ((inv.id = pr.invoice_id)))
          WHERE ((inv.sat_status IS NULL) OR (inv.sat_status <> 'CANCELADO'::public."SatStatus"))
        ), desglose_percepciones AS (
         SELECT b.organization_id,
            b.company_id,
            b.fiscal_entity_id,
            b.anio,
            b.mes,
            b.departamento,
            sum((pp.importe_gravado + pp.importe_exento)) FILTER (WHERE (pp.tipo_percepcion = '001'::text)) AS sueldos_001,
            sum((pp.importe_gravado + pp.importe_exento)) FILTER (WHERE (pp.tipo_percepcion = '002'::text)) AS aguinaldo_002,
            sum((pp.importe_gravado + pp.importe_exento)) FILTER (WHERE (pp.tipo_percepcion = '003'::text)) AS ptu_003,
            sum((pp.importe_gravado + pp.importe_exento)) FILTER (WHERE (pp.tipo_percepcion = '019'::text)) AS horas_extra_019,
            sum((pp.importe_gravado + pp.importe_exento)) FILTER (WHERE (pp.tipo_percepcion = '021'::text)) AS prima_vac_021,
            sum((pp.importe_gravado + pp.importe_exento)) FILTER (WHERE (pp.tipo_percepcion = '028'::text)) AS comisiones_028,
            sum((pp.importe_gravado + pp.importe_exento)) FILTER (WHERE (pp.tipo_percepcion = '038'::text)) AS bonos_038
           FROM (base b
             JOIN public.payroll_percepciones pp ON ((pp.payroll_receipt_id = b.pr_id)))
          WHERE (pp.tipo_percepcion = ANY (ARRAY['001'::text, '002'::text, '003'::text, '019'::text, '021'::text, '028'::text, '038'::text]))
          GROUP BY b.organization_id, b.company_id, b.fiscal_entity_id, b.anio, b.mes, b.departamento
        ), agregaciones AS (
         SELECT base.organization_id,
            base.company_id,
            base.fiscal_entity_id,
            base.anio,
            base.mes,
            base.departamento,
            (count(DISTINCT base.pr_id))::integer AS count_recibos,
            (count(DISTINCT base.empleado_key))::integer AS count_empleados_unicos,
            (COALESCE(sum(base.total_percepciones), (0)::numeric))::numeric(18,6) AS percepciones_brutas_mxn,
            (COALESCE(sum((base.sbc * base.num_dias_pagados)), (0)::numeric))::numeric(18,6) AS sbc_sumado_mxn,
            (COALESCE(max(NULLIF(base.clave_ent_fed, ''::text)), '00'::text))::character varying(2) AS clave_ent_fed_modal
           FROM base
          GROUP BY base.organization_id, base.company_id, base.fiscal_entity_id, base.anio, base.mes, base.departamento
        ), params_financieros AS (
         SELECT a.organization_id,
            a.company_id,
            a.fiscal_entity_id,
            a.anio,
            a.mes,
            a.departamento,
            a.count_recibos,
            a.count_empleados_unicos,
            a.percepciones_brutas_mxn,
            a.sbc_sumado_mxn,
            a.clave_ent_fed_modal,
            ((a.sbc_sumado_mxn * 0.3040))::numeric(18,6) AS _carga_patronal,
            (
                CASE a.clave_ent_fed_modal
                    WHEN '01'::text THEN 0.025
                    WHEN '02'::text THEN 0.020
                    WHEN '03'::text THEN 0.020
                    WHEN '04'::text THEN 0.030
                    WHEN '05'::text THEN 0.020
                    WHEN '06'::text THEN 0.025
                    WHEN '07'::text THEN 0.020
                    WHEN '08'::text THEN 0.020
                    WHEN '09'::text THEN 0.030
                    WHEN '10'::text THEN 0.020
                    WHEN '11'::text THEN 0.025
                    WHEN '12'::text THEN 0.020
                    WHEN '13'::text THEN 0.020
                    WHEN '14'::text THEN 0.020
                    WHEN '15'::text THEN 0.020
                    WHEN '16'::text THEN 0.020
                    WHEN '17'::text THEN 0.020
                    WHEN '18'::text THEN 0.020
                    WHEN '19'::text THEN 0.020
                    WHEN '20'::text THEN 0.030
                    WHEN '21'::text THEN 0.025
                    WHEN '22'::text THEN 0.020
                    WHEN '23'::text THEN 0.020
                    WHEN '24'::text THEN 0.025
                    WHEN '25'::text THEN 0.020
                    WHEN '26'::text THEN 0.020
                    WHEN '27'::text THEN 0.020
                    WHEN '28'::text THEN 0.020
                    WHEN '29'::text THEN 0.020
                    WHEN '30'::text THEN 0.025
                    WHEN '31'::text THEN 0.020
                    WHEN '32'::text THEN 0.020
                    ELSE 0.025
                END)::numeric(8,6) AS _isn_pct
           FROM agregaciones a
        )
 SELECT pf.organization_id,
    pf.company_id,
    pf.fiscal_entity_id,
    pf.anio,
    pf.mes,
    pf.departamento,
    pf.count_recibos,
    pf.count_empleados_unicos,
    pf.percepciones_brutas_mxn,
    pf.sbc_sumado_mxn,
    (round(pf._carga_patronal, 6))::numeric(18,6) AS carga_patronal_estimada_mxn,
    (round((pf.percepciones_brutas_mxn * pf._isn_pct), 6))::numeric(18,6) AS isn_estimado_mxn,
    (round(((pf.percepciones_brutas_mxn + pf._carga_patronal) + (pf.percepciones_brutas_mxn * pf._isn_pct)), 6))::numeric(18,6) AS costo_total_nomina_mxn,
    (COALESCE(dp.sueldos_001, (0)::numeric))::numeric(18,6) AS sueldos_001,
    (COALESCE(dp.aguinaldo_002, (0)::numeric))::numeric(18,6) AS aguinaldo_002,
    (COALESCE(dp.ptu_003, (0)::numeric))::numeric(18,6) AS ptu_003,
    (COALESCE(dp.horas_extra_019, (0)::numeric))::numeric(18,6) AS horas_extra_019,
    (COALESCE(dp.prima_vac_021, (0)::numeric))::numeric(18,6) AS prima_vac_021,
    (COALESCE(dp.comisiones_028, (0)::numeric))::numeric(18,6) AS comisiones_028,
    (COALESCE(dp.bonos_038, (0)::numeric))::numeric(18,6) AS bonos_038,
    (COALESCE(dp.sueldos_001, (0)::numeric))::numeric(18,6) AS costo_fijo_mxn,
    ((((((COALESCE(dp.aguinaldo_002, (0)::numeric) + COALESCE(dp.ptu_003, (0)::numeric)) + COALESCE(dp.horas_extra_019, (0)::numeric)) + COALESCE(dp.prima_vac_021, (0)::numeric)) + COALESCE(dp.comisiones_028, (0)::numeric)) + COALESCE(dp.bonos_038, (0)::numeric)))::numeric(18,6) AS costo_variable_mxn
   FROM (params_financieros pf
     LEFT JOIN desglose_percepciones dp ON (((dp.organization_id = pf.organization_id) AND (dp.company_id = pf.company_id) AND (dp.fiscal_entity_id = pf.fiscal_entity_id) AND (dp.anio = pf.anio) AND (dp.mes = pf.mes) AND ((dp.departamento)::text = (pf.departamento)::text))))
  WITH NO DATA;


ALTER TABLE public.mv_direccion_costo_ejecutivo_mensual OWNER TO postgres;

