ALTER TABLE public.payroll_deducciones OWNER TO postgres;

--
-- Name: mv_fiscal_conciliacion_mensual; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_fiscal_conciliacion_mensual AS
 WITH receipt_base AS (
         SELECT pr.id AS receipt_id,
            pr.organization_id,
            pr.company_id,
            pr.fiscal_entity_id,
            pr.fecha_pago,
            pr.departamento,
            pr.fecha_emision,
            (EXTRACT(year FROM pr.fecha_pago))::integer AS anio,
            (EXTRACT(month FROM pr.fecha_pago))::integer AS mes,
            (COALESCE((inv.sat_status)::text, 'VIGENTE'::text))::character varying AS sat_status,
            (count(*) OVER (PARTITION BY pr.uuid) > 1) AS is_uuid_duplicado
           FROM (public.payroll_receipts pr
             LEFT JOIN public.invoices inv ON ((inv.id = pr.invoice_id)))
        ), ded_agg AS (
         SELECT pd.payroll_receipt_id AS receipt_id,
            sum(
                CASE
                    WHEN (pd.tipo_deduccion = '002'::text) THEN pd.importe
                    ELSE (0)::numeric
                END) AS isr,
            sum(
                CASE
                    WHEN (pd.tipo_deduccion = '010'::text) THEN pd.importe
                    ELSE (0)::numeric
                END) AS infonavit,
            sum(
                CASE
                    WHEN (pd.tipo_deduccion = '006'::text) THEN pd.importe
                    ELSE (0)::numeric
                END) AS fonacot,
            sum(
                CASE
                    WHEN (pd.tipo_deduccion = '007'::text) THEN pd.importe
                    ELSE (0)::numeric
                END) AS pension,
            sum(
                CASE
                    WHEN (pd.tipo_deduccion = '001'::text) THEN pd.importe
                    ELSE (0)::numeric
                END) AS sindicato
           FROM public.payroll_deducciones pd
          WHERE (pd.tipo_deduccion = ANY (ARRAY['001'::text, '002'::text, '006'::text, '007'::text, '010'::text]))
          GROUP BY pd.payroll_receipt_id
        ), perc_agg AS (
         SELECT pp.payroll_receipt_id AS receipt_id,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '001'::text) THEN pp.importe_gravado
                    ELSE (0)::numeric
                END) AS gravado_001,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '001'::text) THEN pp.importe_exento
                    ELSE (0)::numeric
                END) AS exento_001,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '002'::text) THEN pp.importe_gravado
                    ELSE (0)::numeric
                END) AS gravado_002,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '002'::text) THEN pp.importe_exento
                    ELSE (0)::numeric
                END) AS exento_002,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '003'::text) THEN pp.importe_gravado
                    ELSE (0)::numeric
                END) AS gravado_003,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '003'::text) THEN pp.importe_exento
                    ELSE (0)::numeric
                END) AS exento_003,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '021'::text) THEN pp.importe_gravado
                    ELSE (0)::numeric
                END) AS gravado_021,
            sum(
                CASE
                    WHEN (pp.tipo_percepcion = '021'::text) THEN pp.importe_exento
                    ELSE (0)::numeric
                END) AS exento_021
           FROM public.payroll_percepciones pp
          WHERE (pp.tipo_percepcion = ANY (ARRAY['001'::text, '002'::text, '003'::text, '021'::text]))
          GROUP BY pp.payroll_receipt_id
        ), receptor_agg AS (
         SELECT prr.payroll_receipt_id AS receipt_id,
            prr.rfc,
            prr.salario_base_cot_apor AS sbc,
            prr.salario_diario_integrado AS sdi
           FROM public.payroll_receptors prr
        )
 SELECT rb.organization_id,
    rb.company_id,
    rb.fiscal_entity_id,
    rb.anio,
    rb.mes,
    ''::text AS registro_patronal,
    count(*) AS count_receipts,
    count(DISTINCT ra.rfc) AS count_empleados_distinct,
    (COALESCE(sum(COALESCE(da.isr, (0)::numeric)), (0)::numeric))::numeric(18,6) AS isr_retenido_mxn,
    (COALESCE(sum(COALESCE(da.infonavit, (0)::numeric)), (0)::numeric))::numeric(18,6) AS cuotas_infonavit,
    (COALESCE(sum(COALESCE(da.fonacot, (0)::numeric)), (0)::numeric))::numeric(18,6) AS cuotas_fonacot,
    (COALESCE(sum(COALESCE(da.pension, (0)::numeric)), (0)::numeric))::numeric(18,6) AS cuotas_pension,
    (COALESCE(sum(COALESCE(da.sindicato, (0)::numeric)), (0)::numeric))::numeric(18,6) AS cuotas_sindicato,
    (COALESCE(sum(COALESCE(pa.gravado_001, (0)::numeric)), (0)::numeric))::numeric(18,6) AS gravado_001_sueldos,
    (COALESCE(sum(COALESCE(pa.exento_001, (0)::numeric)), (0)::numeric))::numeric(18,6) AS exento_001_sueldos,
    (COALESCE(sum(COALESCE(pa.gravado_002, (0)::numeric)), (0)::numeric))::numeric(18,6) AS gravado_002_aguinaldo,
    (COALESCE(sum(COALESCE(pa.exento_002, (0)::numeric)), (0)::numeric))::numeric(18,6) AS exento_002_aguinaldo,
    (COALESCE(sum(COALESCE(pa.gravado_003, (0)::numeric)), (0)::numeric))::numeric(18,6) AS gravado_003_ptu,
    (COALESCE(sum(COALESCE(pa.exento_003, (0)::numeric)), (0)::numeric))::numeric(18,6) AS exento_003_ptu,
    (COALESCE(sum(COALESCE(pa.gravado_021, (0)::numeric)), (0)::numeric))::numeric(18,6) AS gravado_021_primavac,
    (COALESCE(sum(COALESCE(pa.exento_021, (0)::numeric)), (0)::numeric))::numeric(18,6) AS exento_021_primavac,
    count(*) FILTER (WHERE ((ra.sbc IS NULL) OR (ra.sbc = (0)::numeric))) AS recepciones_sbc_null,
    count(*) FILTER (WHERE ((ra.sdi IS NULL) OR (ra.sdi = (0)::numeric))) AS recepciones_sdi_null,
    count(*) FILTER (WHERE ((ra.sbc IS NOT NULL) AND (ra.sbc > (0)::numeric) AND ((abs((ra.sbc - COALESCE(ra.sdi, (0)::numeric))) / ra.sbc) > 0.03))) AS recepciones_desv_sbc_sdi_gt_3pct,
    count(*) FILTER (WHERE ((rb.sat_status)::text = 'CANCELADO'::text)) AS count_cancelados,
    count(*) FILTER (WHERE (rb.is_uuid_duplicado IS TRUE)) AS count_uuid_duplicados,
    count(*) FILTER (WHERE (abs(((rb.fecha_emision)::date - rb.fecha_pago)) > 5)) AS count_brecha_5dias
   FROM (((receipt_base rb
     LEFT JOIN ded_agg da ON ((da.receipt_id = rb.receipt_id)))
     LEFT JOIN perc_agg pa ON ((pa.receipt_id = rb.receipt_id)))
     LEFT JOIN receptor_agg ra ON ((ra.receipt_id = rb.receipt_id)))
  GROUP BY rb.organization_id, rb.company_id, rb.fiscal_entity_id, rb.anio, rb.mes, ''::text
  WITH NO DATA;


ALTER TABLE public.mv_fiscal_conciliacion_mensual OWNER TO postgres;

--
-- Name: mv_hr_beneficios_prestaciones; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_hr_beneficios_prestaciones AS
 SELECT pr.organization_id,
    pr.company_id,
    pr.fiscal_entity_id,
    COALESCE(pr.departamento, 'Sin Departamento'::text) AS departamento,
    pr.tipo_nomina,
    prre.periodicidad_pago,
    (date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date AS mes_pago,
    pp.tipo_percepcion,
    (
        CASE pp.tipo_percepcion
            WHEN '005'::text THEN 'Fondo/Caja de Ahorro'::text
            WHEN '010'::text THEN 'Premios de Puntualidad'::text
            WHEN '029'::text THEN 'Vales de Despensa'::text
            WHEN '049'::text THEN 'Premios de Asistencia'::text
            ELSE (('Otro ('::text || pp.tipo_percepcion) || ')'::text)
        END)::character varying(64) AS descripcion_beneficio,
    pp.concepto,
    count(*) AS numero_aplicaciones,
    count(DISTINCT prre.rfc) AS empleados_beneficiados,
    sum(pp.importe_gravado) AS total_gravado,
    sum(pp.importe_exento) AS total_exento,
    sum((pp.importe_gravado + pp.importe_exento)) AS importe_total
   FROM ((public.payroll_receipts pr
     JOIN public.payroll_percepciones pp ON ((pp.payroll_receipt_id = pr.id)))
     JOIN public.payroll_receptors prre ON ((prre.payroll_receipt_id = pr.id)))
  WHERE (pp.tipo_percepcion = ANY (ARRAY['005'::text, '010'::text, '029'::text, '049'::text]))
  GROUP BY pr.organization_id, pr.company_id, pr.fiscal_entity_id, COALESCE(pr.departamento, 'Sin Departamento'::text), pr.tipo_nomina, prre.periodicidad_pago, ((date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date), pp.tipo_percepcion, ((
        CASE pp.tipo_percepcion
            WHEN '005'::text THEN 'Fondo/Caja de Ahorro'::text
            WHEN '010'::text THEN 'Premios de Puntualidad'::text
            WHEN '029'::text THEN 'Vales de Despensa'::text
            WHEN '049'::text THEN 'Premios de Asistencia'::text
            ELSE (('Otro ('::text || pp.tipo_percepcion) || ')'::text)
        END)::character varying(64)), pp.concepto
  WITH NO DATA;


ALTER TABLE public.mv_hr_beneficios_prestaciones OWNER TO postgres;

--
-- Name: mv_hr_headcount_costo_kpis; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_hr_headcount_costo_kpis AS
 SELECT pr.organization_id,
    pr.company_id,
    pr.fiscal_entity_id,
    COALESCE(pr.departamento, 'Sin Departamento'::text) AS departamento,
    pr.tipo_nomina,
    prre.periodicidad_pago,
    (date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date AS mes_pago,
    count(DISTINCT pr.id) AS recibos_procesados,
    count(DISTINCT prre.rfc) AS empleados_pagados,
    sum(pr.total_percepciones) AS total_percepciones,
    sum(pr.total_deducciones) AS total_deducciones,
    sum(COALESCE(pr.total_otros_pagos, (0)::numeric)) AS total_otros_pagos,
    sum(pr.num_dias_pagados) AS total_dias_pagados,
    avg(pr.total_percepciones) AS ticket_promedio_percepciones
   FROM (public.payroll_receipts pr
     JOIN public.payroll_receptors prre ON ((prre.payroll_receipt_id = pr.id)))
  GROUP BY pr.organization_id, pr.company_id, pr.fiscal_entity_id, COALESCE(pr.departamento, 'Sin Departamento'::text), pr.tipo_nomina, prre.periodicidad_pago, ((date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date)
  WITH NO DATA;


ALTER TABLE public.mv_hr_headcount_costo_kpis OWNER TO postgres;

