--
-- Name: mv_hr_horas_extra_por_depto; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_hr_horas_extra_por_depto AS
 SELECT pr.organization_id,
    pr.company_id,
    pr.fiscal_entity_id,
    COALESCE(pr.departamento, 'Sin Departamento'::text) AS departamento,
    (date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date AS mes_pago,
    phe.tipo_horas,
    (
        CASE phe.tipo_horas
            WHEN '01'::text THEN 'Dobles'::text
            WHEN '02'::text THEN 'Triples'::text
            ELSE (('Otras ('::text || phe.tipo_horas) || ')'::text)
        END)::character varying(32) AS descripcion_tipo,
    count(DISTINCT pr.id) AS numero_nominas,
    count(DISTINCT prre.rfc) AS empleados,
    sum(phe.horas_extra) AS total_horas,
    sum(phe.dias) AS total_dias,
    sum(phe.importe_pagado) AS importe_total
   FROM ((public.payroll_receipts pr
     JOIN public.payroll_horas_extra phe ON ((phe.payroll_receipt_id = pr.id)))
     JOIN public.payroll_receptors prre ON ((prre.payroll_receipt_id = pr.id)))
  GROUP BY pr.organization_id, pr.company_id, pr.fiscal_entity_id, COALESCE(pr.departamento, 'Sin Departamento'::text), ((date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date), phe.tipo_horas, ((
        CASE phe.tipo_horas
            WHEN '01'::text THEN 'Dobles'::text
            WHEN '02'::text THEN 'Triples'::text
            ELSE (('Otras ('::text || phe.tipo_horas) || ')'::text)
        END)::character varying(32))
  WITH NO DATA;


ALTER TABLE public.mv_hr_horas_extra_por_depto OWNER TO postgres;

