--
-- Name: mv_hr_incapacidades_acumulado; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_hr_incapacidades_acumulado AS
 SELECT pr.organization_id,
    pr.company_id,
    pr.fiscal_entity_id,
    pr.departamento,
    pr.tipo_nomina,
    prre.periodicidad_pago,
    (date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date AS mes_pago,
    prre.rfc AS receptor_rfc,
    pi.tipo_incapacidad,
    (
        CASE pi.tipo_incapacidad
            WHEN '01'::text THEN 'Riesgo de trabajo'::text
            WHEN '02'::text THEN 'Enfermedad general'::text
            WHEN '03'::text THEN 'Maternidad'::text
            ELSE (('Otro ('::text || pi.tipo_incapacidad) || ')'::text)
        END)::character varying(64) AS descripcion_tipo,
    count(*) AS numero_eventos,
    sum(pi.num_dias) AS total_dias,
    avg(pi.num_dias) AS promedio_dias_por_evento,
    sum(pi.importe_monetario) AS importe_total,
    count(DISTINCT prre.rfc) AS empleados_afectados
   FROM ((public.payroll_receipts pr
     JOIN public.payroll_incapacidades pi ON ((pi.payroll_receipt_id = pr.id)))
     JOIN public.payroll_receptors prre ON ((prre.payroll_receipt_id = pr.id)))
  GROUP BY pr.organization_id, pr.company_id, pr.fiscal_entity_id, pr.departamento, pr.tipo_nomina, prre.periodicidad_pago, ((date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date), prre.rfc, pi.tipo_incapacidad, ((
        CASE pi.tipo_incapacidad
            WHEN '01'::text THEN 'Riesgo de trabajo'::text
            WHEN '02'::text THEN 'Enfermedad general'::text
            WHEN '03'::text THEN 'Maternidad'::text
            ELSE (('Otro ('::text || pi.tipo_incapacidad) || ')'::text)
        END)::character varying(64))
  WITH NO DATA;


ALTER TABLE public.mv_hr_incapacidades_acumulado OWNER TO postgres;

--
-- Name: mv_hr_plantilla_actual; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_hr_plantilla_actual AS
 WITH ultimo_recibo_empleado AS (
         SELECT pr.organization_id,
            pr.company_id,
            pr.fiscal_entity_id,
            prre.rfc,
            max(pr.fecha_pago) AS ultima_fecha_pago,
            max(prre.fecha_inicio_rel_laboral) FILTER (WHERE (prre.fecha_inicio_rel_laboral IS NOT NULL)) AS fecha_inicio_rel_laboral,
            max(pr.tipo_nomina) AS tipo_nomina,
            max(prre.periodicidad_pago) AS periodicidad_pago,
            max(prre.tipo_contrato) AS tipo_contrato,
            max(prre.tipo_jornada) AS tipo_jornada,
            max(prre.tipo_regimen) AS tipo_regimen,
            max(prre.departamento) AS departamento,
            max(prre.antiguedad) AS antiguedad_declarada,
            max(prre.salario_diario_integrado) FILTER (WHERE (prre.salario_diario_integrado IS NOT NULL)) AS ultimo_sdi
           FROM (public.payroll_receipts pr
             JOIN public.payroll_receptors prre ON ((prre.payroll_receipt_id = pr.id)))
          GROUP BY pr.organization_id, pr.company_id, pr.fiscal_entity_id, prre.rfc
         HAVING (max(pr.fecha_pago) >= ((now() - '3650 days'::interval))::date)
        )
 SELECT ultimo_recibo_empleado.organization_id,
    ultimo_recibo_empleado.company_id,
    ultimo_recibo_empleado.fiscal_entity_id,
    COALESCE(ultimo_recibo_empleado.departamento, 'Sin Departamento'::text) AS departamento,
    ultimo_recibo_empleado.tipo_nomina,
    ultimo_recibo_empleado.periodicidad_pago,
    COALESCE(ultimo_recibo_empleado.tipo_contrato, 'Sin Especificar'::text) AS tipo_contrato,
    COALESCE(ultimo_recibo_empleado.tipo_jornada, 'Sin Especificar'::text) AS tipo_jornada,
    count(DISTINCT ultimo_recibo_empleado.rfc) AS num_empleados,
    (avg(
        CASE
            WHEN (ultimo_recibo_empleado.fecha_inicio_rel_laboral IS NOT NULL) THEN ((EXTRACT(epoch FROM (now() - (ultimo_recibo_empleado.fecha_inicio_rel_laboral)::timestamp with time zone)) / (365.25 * 86400.0)))::double precision
            ELSE ((COALESCE(ultimo_recibo_empleado.antiguedad_declarada, 0))::double precision / (12.0)::double precision)
        END))::numeric(8,2) AS antiguedad_promedio_anios,
    (avg(ultimo_recibo_empleado.ultimo_sdi))::numeric(18,6) AS sdi_promedio
   FROM ultimo_recibo_empleado
  GROUP BY ultimo_recibo_empleado.organization_id, ultimo_recibo_empleado.company_id, ultimo_recibo_empleado.fiscal_entity_id, COALESCE(ultimo_recibo_empleado.departamento, 'Sin Departamento'::text), ultimo_recibo_empleado.tipo_nomina, ultimo_recibo_empleado.periodicidad_pago, COALESCE(ultimo_recibo_empleado.tipo_contrato, 'Sin Especificar'::text), COALESCE(ultimo_recibo_empleado.tipo_jornada, 'Sin Especificar'::text)
  WITH NO DATA;


ALTER TABLE public.mv_hr_plantilla_actual OWNER TO postgres;

--
-- Name: mv_hr_turnover_mensual; Type: MATERIALIZED VIEW; Schema: public; Owner: postgres
--

CREATE MATERIALIZED VIEW public.mv_hr_turnover_mensual AS
 WITH max_mes_company AS (
         SELECT payroll_receipts.company_id,
            max((date_trunc('month'::text, (payroll_receipts.fecha_pago)::timestamp with time zone))::date) AS max_mes_pago
           FROM public.payroll_receipts
          GROUP BY payroll_receipts.company_id
        ), recepciones_por_mes AS (
         SELECT pr.organization_id,
            pr.company_id,
            pr.fiscal_entity_id,
            pr.departamento,
            pr.tipo_nomina,
            prre.periodicidad_pago,
            prre.rfc AS receptor_rfc,
            (date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date AS mes_pago,
            min(pr.fecha_pago) AS primera_fecha_pago,
            max(pr.fecha_pago) AS ultima_fecha_pago,
            count(DISTINCT pr.uuid) AS recibos_mes
           FROM (public.payroll_receipts pr
             JOIN public.payroll_receptors prre ON ((prre.payroll_receipt_id = pr.id)))
          GROUP BY pr.organization_id, pr.company_id, pr.fiscal_entity_id, pr.departamento, pr.tipo_nomina, prre.periodicidad_pago, prre.rfc, ((date_trunc('month'::text, (pr.fecha_pago)::timestamp with time zone))::date)
        ), lag_lead AS (
         SELECT r.organization_id,
            r.company_id,
            r.fiscal_entity_id,
            r.departamento,
            r.tipo_nomina,
            r.periodicidad_pago,
            r.receptor_rfc,
            r.mes_pago,
            r.primera_fecha_pago,
            r.ultima_fecha_pago,
            r.recibos_mes,
            lag(r.mes_pago) OVER (PARTITION BY r.organization_id, r.company_id, r.tipo_nomina, r.periodicidad_pago, r.receptor_rfc ORDER BY r.mes_pago) AS mes_anterior,
            lead(r.mes_pago) OVER (PARTITION BY r.organization_id, r.company_id, r.tipo_nomina, r.periodicidad_pago, r.receptor_rfc ORDER BY r.mes_pago) AS mes_siguiente,
            m.max_mes_pago
           FROM (recepciones_por_mes r
             JOIN max_mes_company m ON ((m.company_id = r.company_id)))
        )
 SELECT lag_lead.organization_id,
    lag_lead.company_id,
    lag_lead.fiscal_entity_id,
    lag_lead.departamento,
    lag_lead.tipo_nomina,
    lag_lead.periodicidad_pago,
    lag_lead.mes_pago,
    (count(*) FILTER (WHERE ((lag_lead.mes_anterior IS NULL) OR ((lag_lead.mes_pago - lag_lead.mes_anterior) > 60))))::integer AS altas,
    (count(*) FILTER (WHERE (((lag_lead.mes_siguiente IS NULL) AND ((lag_lead.max_mes_pago - lag_lead.mes_pago) > 60)) OR ((lag_lead.mes_siguiente - lag_lead.mes_pago) > 60))))::integer AS bajas,
    (count(*) FILTER (WHERE ((lag_lead.mes_anterior IS NOT NULL) AND ((lag_lead.mes_pago - lag_lead.mes_anterior) > 60))))::integer AS reingresos,
    count(DISTINCT lag_lead.receptor_rfc) AS empleados_activos,
    sum(lag_lead.recibos_mes) AS total_recibos
   FROM lag_lead
  GROUP BY lag_lead.organization_id, lag_lead.company_id, lag_lead.fiscal_entity_id, lag_lead.departamento, lag_lead.tipo_nomina, lag_lead.periodicidad_pago, lag_lead.mes_pago
  WITH NO DATA;


ALTER TABLE public.mv_hr_turnover_mensual OWNER TO postgres;

